import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Аванпосты: готовность, администрирование и изолированная приёмка","description":"","frontmatter":{"pageId":"admins/passive-outposts","contentRevision":23},"headers":[],"relativePath":"ru/admins/passive-outposts.md","filePath":"ru/admins/passive-outposts.md"}'),i={name:"ru/admins/passive-outposts.md"};function c(n,e,s,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="аванпосты-готовность-администрирование-и-изолированная-приемка" tabindex="-1">Аванпосты: готовность, администрирование и изолированная приёмка <a class="header-anchor" href="#аванпосты-готовность-администрирование-и-изолированная-приемка" aria-label="Permalink to &quot;Аванпосты: готовность, администрирование и изолированная приёмка&quot;">​</a></h1><h2 id="usage" tabindex="-1">Product остаётся Pending <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Product остаётся Pending {#usage}&quot;">​</a></h2><p>Executor 10.0.14 использует отдельную квалификацию rimlink-outposts-schema-20261107-runtime14 и её профиль provider-v1; историческая квалификация 10.0.13 не изменена. Qualification, provider profile и recorded Framework должны совпадать одним точным tuple. Неизвестные patches и смешанные tuple отклоняются. Fresh/pre-DDL исполнение сохраняет точное равенство artifact hash/MVID/provider/recipe; после доказанного post-schema состояния legacy witness проверяется по прежнему no-DDL пути. Runtimeconfig сервера и CLI явно требует 10.0.14; не обходите эту политику runtime override.</p><p>Версия проекта — 0.9.2; изменение версии само по себе не включает Product.</p><p>Версия 0.9.2 поставляет встроенный build-артефакт Pending. <code>Outposts:Enabled=true</code>, учётная запись администратора, миграция schema, подтверждённый манифест или успешная локальная сборка не квалифицируют Product. В релизе capability остаётся выключенной. Обновляйте сервер и клиентский мод вместе.</p><p>Единый evaluator показывает настройку, десять фиксированных интеграций защиты и ревизии контрактов, квалификацию сборки, фактический startup state, доказанный цепочкой domain format, текущую schema, объявленную capability, восстановление custody и защиту истории. Unknown закрывает доступ. <code>Enabled=false</code> закрывает новые игровые операции, но не снимает custody fences. Мигрированный domain v1 — <code>FormatActivationRequired</code>, а не повреждённая история: доступны чтение и явная активация v2, обычные domain writers закрыты. <code>NoActiveWorld</code> остаётся административным состоянием. Только существующий доказанный Completed Recreate может связать successor world через отдельный вывод evaluator; ordinary recovery до реального Ready не открывается.</p><h2 id="commands" tabindex="-1">Проверить, подготовить, сохранить и подтвердить <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Проверить, подготовить, сохранить и подтвердить {#commands}&quot;">​</a></h2><p>Используйте экран «Аванпосты» существующей панели или <code>rimlink-tools admin outposts</code> через обычный аутентифицированный REST. GET требует Read; upload, preview и commit — Admin, дополнительно действует проверка роли в service. Панель сохраняет session/CSRF-канал. Подтверждение game-admin проходит через тот же canonical command service с дополнительными protobuf-полями; старая команда только с ID/digest отклоняется.</p><p>CLI поддерживает <code>inspect [--player ID] [--operation ID] [--limit N] [--cursor VALUE]</code>, <code>preview --request FILE</code>, <code>initialize --request FILE</code>, <code>activate-domain-format --request FILE</code>, <code>resolve --request FILE</code> и <code>manifest inspect ID|upload FILE|confirm --request FILE</code>. Он вызывает только REST, не открывает работающую БД и не вычисляет новый intent digest.</p><p>Draft предпросмотра содержит action, новый requestId в D-формате, причину длиной 1..1024 байт UTF-8 и только типизированные поля выбранного действия. Сервер связывает аутентифицированного инициатора, observation, evidence, allocations и intent. Hash задаётся 64 строчными hex-символами; canonical command передаётся base64 и ограничен 64 КиБ. Чтение возвращает до 100 строк/1 МиБ. JSON transport ограничен 2 МиБ для необязательного base64 OriginalOrdinaryInput, сам бинарный sidecar — 1 МиБ. Точный исходный ввод декодируется и проверяется в памяти: он не считается доказательством отсутствия источника, не логируется, не сохраняется на серверный staging-диск и не входит в command/audit. Восстановить отсутствующий RPC по hash нельзя.</p><p>До отправки с <code>confirmed:true</code> сохраните всю возвращённую команду. CLI принимает сохранённый preview envelope и исключает диагностические <code>intent</code>/<code>blockers</code>, отправляя исходные command/digest. Панель требует сохранить команду и отдельно подтвердить её. Изменение ввода сбрасывает предпросмотр. Изменившиеся head/state/evidence отклоняют прежний выбор: новый preview и подтверждение запрашиваются явно. Адаптеры не обновляют и не отправляют замену молча. Неопределённый ответ требует сохранить исходную команду; ошибка не доказывает durable rejection и не разрешает повторную выдачу.</p><p>Инициализация требует доказанно пустой защищённой истории, физически подготовленного квалифицированного NULL anchor, фактического world binding и точного наблюдения schema/backend/location. Она не инициализирует историю поверх отсутствующей или повреждённой authority. Прерванная инициализация требует той же полной исходной команды с allocations; одного digest недостаточно. Физическая подготовка и restore/resume/backout остаются отдельными процедурами при остановленном сервере, а не online-кнопками ремонта.</p><h2 id="recovery" tabindex="-1">Манифест и варианты восстановления <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Манифест и варианты восстановления {#recovery}&quot;">​</a></h2><p>Перед первым экспортом заполните серверный каталог определениями из активного модпака. Полный каталог должен включать названия биомов основной планеты, а также <code>Steel</code> и <code>WoodLog</code>. Команда <code>rimlink-tools modpack defs</code> сканирует только ThingDef и PawnKindDef. Чтобы передать полный список с биомами, используйте <code>PUT /api/admin/modpack/defs</code> с авторизацией и телом <code>{&quot;defNames&quot;:[...]}</code>. Запрос заменяет весь каталог, поэтому при добавлении биомов сохраните имена разрешённых предметов и видов пешек. Сервер отклоняет манифест мира при пустом каталоге.</p><p>Экспортируйте реальный мир администратора на основном потоке игры. Для манифеста используются канонические параметры сервера после сверки фактической планеты. Локальный сценарий колонии, рассказчик и сложность могут отличаться. Планета, сборка игры, DLC и игровые определения должны совпадать. Передавайте точный бинарный документ порциями до 256 КиБ, общий размер — до 24 МиБ. Staging является защищённым изменением и не подтверждает документ. Проверьте отпечатки мира, параметров, defs/DLC/catalog, покрытие тайлов, revision/digest и число затронутых владельцев, подготовок и аванпостов. Затем запросите отдельный confirmation preview с причиной. Изменение географии, затрагивающее custody, требует полного квалифицированного recovery graph. Подтверждение применяет существующие settle/hold-правила, сохраняет происхождение данных, не включает Product и не угадывает прошедшую добычу под SafetyHold.</p><p>После восстановления из полной резервной копии колония без защищённой истории аванпостов может загружать обычные сохранения, даже если в копии уже было её сохранение. Сервер сверяет поколение и эпоху записи с восстановленной колонией, проверяет файл и метаданные сохранения. При первом защищённом снимке в восстановленном мире сервер проверяет наличие защищённой истории в сохранённой резервной копии. Для колонии с такой историей по-прежнему требуются подтверждение канонического снимка и restore bridge. Подтверждённую передачу от другого игрока можно подготовить после нового обычного сохранения восстановленной колонии. Работник остаётся у отправителя по учёту custody, пока сервер не примет защищённое сохранение с квитанцией получателя. Ожидающая посылка из полной резервной копии продолжает использовать свой исходный подтверждённый манифест. Перед чтением документа сервер сверяет сохранённое разрешение восстановления с посылкой, получателем и текущей областью действия. Последующий отзыв создаёт новую запись возврата в текущей области действия и сохраняет исходные данные назначения.</p><p>Архивация и восстановление колонии, на которую распространяется текущее полное восстановление, проходят через защищённый журнал операций, в том числе для обычных сохранений. Для архива, уже входившего в выбранную резервную копию, сервер сверяет владельца, поколение, манифест и хеши файлов с этой копией. Архив, созданный после полного восстановления без записи в журнале операций, требует восстановления. При отказе проверки сохраните исходный архив и его доказательства.</p><p>Перед фиксацией защищённых изменений сервер проверяет сохранённые файлы резервных копий и происхождение вложенных копий. SQLite открывается во временной копии для проверки, после чего сервер снова сверяет состав и хеши исходных файлов. Файлы, от которых зависит продолжение или откат восстановления, по-прежнему записываются с гарантией долговечности.</p><p>Клиент отсчитывает 30 секунд до следующего автоматического опроса после завершения текущего. При медленной проверке защищённых данных это оставляет время на команды владельца между опросами.</p><p>Resolve ограничен ExistingTerminal, AbortNoRemoval, AbortWithReturn, OrdinaryReturn и CanonicalDownload. Каждый путь перепроверяет неизменяемый источник, исходный scope, текущий canonical proof и точное состояние операции. Перемещение имущества дополнительно требует квалифицированной recovery readiness. Уже принятые/applied исходы не создают вторую передачу; неизвестное изъятие не превращается в отрицательное доказательство. CanonicalDownload выбирает существующий разрешённый snapshot/provenance и требует owner download/reconciliation, а не spawn, новый epoch или переписывание исторического payload. Исторические исходы содержат NoReplayAuthorization.</p><p>Диагностика archive/reset/backup является advisory. Наблюдение readiness не выполняет полную lifecycle-validation под блокировками: такой результат — Unknown с названием необходимой проверки, а не Allowed. Доказанный readiness blocker — Denied. Сохраняйте артефакты и используйте существующую явную операцию/preflight; чтение не рассчитывает production. Offline-процедуры описаны в <a href="./backup-recovery">резервном копировании и восстановлении</a>.</p><h2 id="acceptance" tabindex="-1">Изолированный host и build-only qualification <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;Изолированный host и build-only qualification {#acceptance}&quot;">​</a></h2><p><code>tools/Rimlink.OutpostAcceptanceHost</code> — dev-only executable, исключённый из обычных публикуемых server/CLI/mod-артефактов и итогового Docker image. Он использует тот же application builder, routes, backend, authorization и storage checks. Внутренний несериализуемый provider обозначает IsolatedAcceptance/Pending и снимает только циклическое требование уже иметь будущий Product acceptance seal. Интеграции, автоматические prerequisites, client versions, authority, точные proofs и locks обязательны. Обычной runtime-настройки для этого режима нет.</p><p>Dev executable содержит реальные файлы панели в build output и выбирает этот явный web root. Проверка байтов панели по встроенному source inventory не заменяет проверку отображения в браузере. Admin-only host откладывает создание domain writers и допускает их, когда тот же evaluator наблюдает реальный Ready после доказанного successor bind. Запущенные writers продолжают перепроверять gate.</p><p>Перед отдельно разрешённым запуском Task16 явный descriptor связывает канонический частный root с отдельными data, внешним anchor, backups/archive, копией игры и двумя save roots; уникальные принадлежащие стенду host/guest game IDs; точные скомпилированные mod/companion/core/protocol binaries; loopback port; configuration и prerequisite files. Preparation принимает только пустое частное состояние и не подготавливает authority. Reparse/alias-пути, hard links в принадлежащем стенду состоянии, чужие файлы, изменённая конфигурация, несовпавшие binary identities/evidence или вторая ownership lock приводят к отказу. Restart повторяет проверки. Host очищает унаследованные configuration sources и загружает только файл стенда; он не копирует production auth, не запускает общие игры, не меняет MCP-конфигурацию и не завершает процессы.</p><p>Build-only <code>scripts/Seal-OutpostQualification.ps1</code> пересобирает dev tool перед проверкой явного evidence record. Candidate остаётся Pending. Seal отказывает без PASS для каждого обязательного автоматического сценария, фактических G1–G7, реального итогового Astra review всей ветки и проверенных исправлений для точного встроенного safety-source identity, с совпадающим SHA-256 evidence-файлов. Синтетические unit-records проверяют только логику отказа/evaluation и не являются приёмкой. Реальный seal не создавался. Артефакт встраивается в следующую сборку и исключён из собственного source hash; runtime configuration, admin API, data/anchor и скопированный backup его не меняют. Изменение соответствующих исходников обесценивает прежнюю квалификацию.</p><p>Для нового положительно пустого остановленного стенда предусмотрена отдельная команда <code>provision &lt;stand.json&gt;</code>: она вызывает штатный <code>OutpostAnchorStore.Provision()</code>, проверяет физический singleton Record=NULL и не создаёт logical authority. <code>prepare</code> и <code>run</code> этого не делают. Повторный provision, история, частичный store или занятая блокировка приводят к отказу с сохранением файлов.</p><p>Private controller доступен только через канал текущего пользователя с точными stand/run/source identity и случайным nonce. <code>run &lt;stand.json&gt;</code> фиксирует попытку запуска и публикует журнал часов после стартовых проверок и проверки реального значения <code>OutpostClock</code>. Ранние отказы записываются отдельно. Последующий <code>restart &lt;stand.json&gt; &lt;previous-run-id&gt; &lt;downtime-ticks&gt;</code> требует завершённого журнала того же исходного кода, фиксирует его SHA-256 и явно заданный неотрицательный downtime. Опубликованные журналы сохраняются, включая незавершённые. Проверка сохранённых checkpoints запрещает начало в прошлом. Private TimeProvider подключён только к <code>OutpostClock</code>. Положительный идемпотентный шаг двигает согласованные UTC и монотонные часы, остальные службы и транспортные таймеры используют обычное время. Журнал содержит исходную привязку, реальный Sample, запланированные и применённые шаги, часы процесса и завершение. Ошибка записи закрывает дальнейшие шаги и qualification стенда.</p><p>Dev companion связывает pause controls с подтверждением живого private host, точными загруженными binaries, собственными game/savedata и текущей login/session. Точки ожидания различают durable local save, accepted save, removal и cleanup; внутри атомарного удаления партии ожиданий нет. Смена игры, menu/visit, disconnect/relogin или cancellation инвалидируют ожидание. Для lost-reply server interceptor удерживает настоящий ответ после завершения сервиса и до передачи gRPC; он не создаёт подставной успешный ответ. Эти инструменты воспроизводят границы и сами по себе не доказывают прохождение G1–G7.</p><p>Для G2 предусмотрены отдельные entry pauses настоящих Prepare/Commit после обычной authentication/capability gate и до business service. Они связывают текущую session, scope, original operation и intent digest. Reached-entry не доказывает отсутствие результата другого replay. After-durable pause и потерянный transport reply фиксируются отдельно.</p><p>Для G3 <code>rimlink/outpost_acceptance_fault</code> управляет одним dev-only fault выбранного настоящего protected parcel. <code>delivery-placement-fail-after-prefix</code> сверяет DLL игры с проверенными сборками RimWorld 1.7.4998 и 1.7.5000 и записывает хеш загруженной DLL в доказательства прогона. Внутри штатного drop-вызова он записывает фактические object references, quantities, worker UUID и контейнеры, затем прерывает выдачу только при <code>0 &lt; placed &lt; total</code>. На main thread нет ожидания или сетевого вызова. <code>delivery-definition-unavailable</code> однократно запрещает существующий lookup одного реально заявленного <code>thing:&lt;defName&gt;</code> либо <code>kind:&lt;defName&gt;</code>; это явно обозначенная fault injection, не изменение DefDatabase или проверка настоящего cross-mod login. До arm заново проверяются private host, текущая сессия и подлинная посылка. Отдельная private запись наблюдает настоящий write fence и отсутствие local materialization receipt перед штатным abort; hook не устанавливает эти flags. При отказе проверки совместимости защищённой партии в текущей домашней игре до размещения игра ставится на паузу и блокирует сохранения. Посылка остаётся на сервере. Полная выдача без receipt и <code>held</code> без <code>WritesBlocked</code> не считаются доказательством частичной выдачи и блокировки. Эти сценарии ещё требуют реального игрового прогона; сборка инструментов не является PASS G3.</p><p>Тестовая пауза <code>delivery-before-materialize</code> задерживает настоящую выдачу после ответа сервера и до размещения объектов на карте. Выход в главное меню отменяет ожидание. Компаньон читает отменённую паузу в меню по точному ID посылки и операции. Отдельно проверьте, что посылка осталась на сервере, размещения и квитанции нет.</p><p>Игра откладывает фоновое обновление аванпостов и запуск нового прохода восстановления, пока этот клиент назначает работников, выполняет команду владельца или получает защищённую посылку. Типизированные запросы аванпостов ждут до двух минут, пока сервер проверяет сохранённую историю восстановления. Смена сессии или игры по-прежнему отменяет запрос. Если чтение страницы манифеста превысило срок, клиент запрашивает ту же страницу ещё один раз в той же сессии и сохраняет уже прочитанные страницы. Перед изменением custody или выдачей клиент по-прежнему проверяет полный хеш манифеста и совместимость локальной игры.</p><p>После полного восстановления клиент перед повтором операций сверяет мир, владельца, generation, write epoch и границу восстановления с данными текущей сессии. Записи outbox с доказанной другой областью сохраняются вместе с исходным документом. Проверенное ожидающее сохранение той же колонии из прежней границы остаётся в файле <code>.restore-boundary-….rws</code> с исходным журналом и флагом. Клиент загружает каноническое сохранение сервера. При неоднозначных или повреждённых данных по-прежнему требуется восстановление.</p><p>Offline dev-адаптер предоставляет <code>offline-inspect &lt;stand.json&gt; &lt;archive&gt;</code>, <code>offline-backout-inspect &lt;stand.json&gt; &lt;restore-id&gt;</code> и <code>offline &lt;stand.json&gt; &lt;invocation.json&gt;</code>. Invocation version=1 явно выбирает <code>execute</code>, <code>resume</code> или <code>backout</code>: Execute/Backout требуют собственного requestFile и отдельного confirmationDigest, Resume — исходного restoreId. Все пути, исходный request/journal и descriptor привязаны к своему стенду. Общий со штатным CLI codec сохраняет прежний строгий JSON: request 1..32 МиБ, depth 32, без duplicate/unknown properties; Anchor ByteString — массив byte 0..255, до 4096 элементов. Новый confirmation или repair grant не создаётся.</p><p>Существующий restore Checkpoint удерживает только отдельный worker. Private controller наблюдает опубликованную запись, не открывая mutable DB. Arm выбирает literal hook, точный относительный inventory path при необходимости и occurrence после этого arm. Перед Reached event долговечно записывается с readback, actual journal identity/phase/revision и реальными часами процесса. Release требует точных armId/sequence/event SHA-256, неизменённых исходников и journal; повтор команды идемпотентен. До 64 arms и 256 mutating control commands на run, ожидание до 120 секунд; потеря heartbeat на 30 секунд отменяет worker через обычный cancellation/error путь. Ни cancellation, ни Refused/Maintenance не означают доказанный NoEffect. Hard interruption своего CLI и последующие inspect→явный Resume/Backout проверяют настоящие файлы, native journal, main/external completion и publication. GUI-игры управляются отдельно через разрешённый CUA Driver. Сам адаптер не является свидетельством прохождения G6 или power-loss proof.</p><p>Для независимых G6 cases допустима последовательная подготовка одного stopped stand через штатный restore настоящего более нового cutB, затем отдельный restore cutA с новыми ID/boundary. Следующий case начинается только после доказанного terminal состояния предыдущего; незавершённый journal нельзя сбрасывать новым Execute или копированием DB/anchor. Реальные replace/delete подтверждаются inventory и hooks. Missing-path fault сохраняет согласованный полный набор anchor artifacts и проверяет refusal/Maintenance при отсутствующем исходном пути, включая повторный startup. Сохранённый store не является безвозвратно потерянным и не даёт права заявлять successful LostAnchorRecovery. Снять этот fixture fault можно только после остановки, проверки неизменных исходных bytes и отсутствия intervening domain/fence changes. Отдельный same-boundary older-DB negative и реальный successful fresh-boundary restore остаются обязательными.</p><h2 id="limits" tabindex="-1">Ограничения и состояние проверок <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и состояние проверок {#limits}&quot;">​</a></h2><p>При обновлении RimWorld соберите мод и тестовый компаньон под установленную версию и повторите изолированные игровые проверки на ней. При изменении версии игры или игрового содержимого также нужен совместимый подтверждённый манифест. Сборку для приёмки проверяли на RimWorld 1.7.5000.</p><p>SQL immutable triggers в миграциях аванпостов содержит явные CRLF-байты: checkout исходников с LF создаёт тот же квалифицированный каталог. Шесть существующих ProfileId и digest не изменены; неизвестный каталог с LF-only triggers по-прежнему отклоняется без repair. Обновление assembly не подменяет executor уже замороженного restore plan.</p><p>Реальная приёмка G1–G7 завершена на изолированных стендах с двумя клиентами; затем выполнены одно итоговое ревью ветки и проверка всех семи обязательных исправлений. Свидетельства сохраняют границы своих исходников и сборок: затронутые игровые маршруты проверены четырьмя реальными сценариями, а последняя серверная граница оценки стоимости — отдельно. Эти результаты не переоформлялись в Product qualification для релизной сборки. Product остаётся Pending/off. Сборки и целевые unit/RPC-проверки не заменяют два реальных клиента. Не удаляйте server.lock, save-storage.lock, anchor, return fence или restore journal ради принудительной готовности.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./../players/passive-outposts">Игровой сценарий и ограничения custody</a></li><li><a href="./api">REST API</a></li><li><a href="./cli">CLI</a></li><li><a href="./backup-recovery">Резервное копирование и восстановление</a></li><li><a href="./../developers/testing">Проверки для разработчиков</a></li></ul>',43)])])}const h=o(i,[["render",c]]);export{m as __pageData,h as default};
